sp_widget.client_script:
api.controller = function($scope, spModal) {
  var c = this;
  c.currentFilter = 'ALL';
  c.searchQuery = '';
  c.auditing = false;

  // Filter selection handler
  c.setFilter = function(filter) {
    c.currentFilter = filter;
  };

  // Client-side filtering logic
  c.filterInsights = function(item) {
    var matchesFilter = true;
    if (c.currentFilter === 'Financial') matchesFilter = (item.category === 'Financial Proof');
    else if (c.currentFilter === 'OPT') matchesFilter = (item.category === 'OPT/CPT Limit');
    else if (c.currentFilter === 'High') matchesFilter = (item.severity === 'High');

    if (!matchesFilter) return false;

    if (!c.searchQuery) return true;
    var q = c.searchQuery.toLowerCase();
    return (
      (item.insight_id && item.insight_id.toLowerCase().indexOf(q) !== -1) ||
      (item.student_name && item.student_name.toLowerCase().indexOf(q) !== -1) ||
      (item.case_id && item.case_id.toLowerCase().indexOf(q) !== -1) ||
      (item.category && item.category.toLowerCase().indexOf(q) !== -1) ||
      (item.summary && item.summary.toLowerCase().indexOf(q) !== -1)
    );
  };

  // Run AI Audit Scan
  c.runComplianceAudit = function() {
    c.auditing = true;
    c.server.get({ action: 'run_ai_scan' }).then(function(response) {
      c.data = response.data;
      c.auditing = false;
      spModal.alert('AI Compliance Audit Complete! Processed ' + c.data.insights.length + ' active anomaly flags.');
    });
  };

  // Resolve Anomaly
  c.resolveAnomaly = function(item) {
    spModal.open({
      title: 'Resolve Anomaly Flag - ' + item.insight_id,
      message: 'Mark this compliance discrepancy as verified by DSO for student ' + item.student_name + '?',
      buttons: [
        { label: 'Cancel', cancel: true },
        { label: 'Mark Resolved', primary: true }
      ]
    }).then(function(confirmed) {
      if (confirmed) {
        c.server.get({
          action: 'resolve_insight',
          sys_id: item.sys_id
        }).then(function(response) {
          if (response.data.success) {
            var index = c.data.insights.indexOf(item);
            if (index > -1) {
              c.data.insights.splice(index, 1);
            }
            c.data.flaggedAnomalies = Math.max(0, c.data.flaggedAnomalies - 1);
          }
        });
      }
    });
  };
};

sp_widget.css:
.vg-ai-compliance-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #2b3674;
  padding: 10px;

  /* Hero Banner */
  .vg-hero-banner {
    background: linear-gradient(135deg, #091e3a 0%, #0d3a78 100%);
    border-radius: 12px;
    padding: 24px 30px;
    color: #ffffff;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 8px 20px rgba(9, 30, 58, 0.15);
    margin-bottom: 24px;

    .hero-content {
      h2 {
        margin: 0 0 6px 0;
        font-weight: 700;
        font-size: 24px;
        color: #ffffff;
      }
      p {
        margin: 0;
        font-size: 13px;
        opacity: 0.85;
      }
    }

    .btn-hero-outline {
      border: 1px solid rgba(255, 255, 255, 0.4);
      background: rgba(255, 255, 255, 0.08);
      color: #ffffff;
      font-weight: 600;
      font-size: 13px;
      padding: 8px 18px;
      border-radius: 8px;
      transition: all 0.2s ease;

      &:hover {
        background: #ffffff;
        color: #0d3a78;
      }
    }
  }

  /* Metric Cards Row */
  .metric-row {
    margin-bottom: 24px;
  }

  .vg-metric-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    gap: 16px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;

    .metric-icon {
      width: 52px;
      height: 52px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;

      &.blue-circle { background: #e8f0fe; color: #0066ff; }
      &.orange-circle { background: #fef3d6; color: #ff9f43; }
      &.green-circle { background: #e6f4ea; color: #00b074; }
      &.red-circle { background: #fde8e8; color: #ea5455; }
    }

    .metric-data {
      display: flex;
      flex-direction: column;

      .metric-number {
        font-size: 24px;
        font-weight: 700;
        line-height: 1.1;
        margin-bottom: 3px;
      }

      .metric-label {
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.5px;
        color: #8f9bba;
        text-transform: uppercase;
        margin-bottom: 3px;
      }

      .metric-subtext {
        font-size: 11px;
        font-weight: 600;
      }
    }
  }

  /* Text Colors */
  .text-blue { color: #0066ff; }
  .text-orange { color: #ff9f43; }
  .text-green { color: #00b074; }
  .text-red { color: #ea5455; }

  /* Main Card Container */
  .vg-card {
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;
    padding: 20px 24px;

    .vg-card-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 16px;
      border-bottom: 1px solid #f0f3f8;
      margin-bottom: 16px;
      flex-wrap: wrap;
      gap: 12px;

      h4 {
        margin: 0;
        font-size: 16px;
        font-weight: 700;
        color: #1b2559;

        i {
          color: #0066ff;
          margin-right: 8px;
        }
      }

      .header-right {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .filter-pills {
        background: #f4f7fe;
        padding: 3px;
        border-radius: 8px;

        .btn {
          border: none;
          background: transparent;
          color: #8f9bba;
          font-weight: 600;
          font-size: 12px;
          border-radius: 6px;
          padding: 5px 12px;

          &.active {
            background: #ffffff;
            color: #0066ff;
            box-shadow: 0 2px 6px rgba(0,0,0,0.06);
          }
        }
      }

      .search-wrapper {
        position: relative;

        .search-icon {
          position: absolute;
          left: 10px;
          top: 9px;
          color: #8f9bba;
          font-size: 12px;
        }

        .search-input {
          padding-left: 28px;
          border-radius: 8px;
          border: 1px solid #e0e5f2;
          background: #f4f7fe;
          font-size: 12px;
          width: 230px;

          &:focus {
            background: #ffffff;
            border-color: #0066ff;
          }
        }
      }
    }
  }

  /* Table Styling */
  .vg-table {
    margin: 0;

    th {
      font-size: 11px;
      text-transform: uppercase;
      font-weight: 700;
      color: #8f9bba;
      letter-spacing: 0.5px;
      border-bottom: 2px solid #eef2f7;
      border-top: none;
      padding: 12px 8px;
    }

    td {
      vertical-align: middle;
      font-size: 13px;
      color: #2b3674;
      border-top: 1px solid #f4f7fe;
      padding: 12px 8px;
    }

    .case-id-badge {
      font-weight: 700;
      color: #0066ff;
      background: #e8f0fe;
      padding: 4px 8px;
      border-radius: 6px;
      font-size: 12px;
      font-family: monospace;
    }

    .student-cell {
      display: flex;
      flex-direction: column;

      .student-name {
        font-weight: 700;
        color: #1b2559;
      }

      .student-id {
        font-size: 11px;
        color: #8f9bba;
      }
    }

    .type-badge {
      background: #f4f7fe;
      color: #4318ff;
      padding: 4px 8px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: 600;
    }

    .risk-pill {
      display: inline-block;
      padding: 3px 10px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: 700;

      &.risk-low { background: #e6f4ea; color: #00b074; }
      &.risk-med { background: #fef3d6; color: #ff9f43; }
      &.risk-high { background: #fde8e8; color: #ea5455; }
    }

    .insight-summary-box {
      display: flex;
      align-items: flex-start;
      gap: 8px;
      font-size: 12px;
      color: #2b3674;

      i { margin-top: 2px; }
    }

    .btn-review {
      background: #f4f7fe;
      color: #0066ff;
      font-weight: 600;
      border: 1px solid #e0e5f2;
      border-radius: 6px;
      padding: 4px 12px;

      &:hover {
        background: #0066ff;
        color: #ffffff;
      }
    }
  }

  .pad-lg { padding: 30px !important; }
}

sp_widget.script:
(function() {
  /* Dynamic AI Compliance Insights Engine */
  data.complianceScore = 94;
  data.flaggedAnomalies = 5;
  data.cptOptMismatches = 2;
  data.verifiedFilesCount = 128;

  data.insights = [];

  var caseTable = 'sn_hr_core_case';

  // Handle server actions
  if (input && input.action === 'run_ai_scan') {
    data.complianceScore = 96;
    data.flaggedAnomalies = 4;
    data.cptOptMismatches = 1;
    data.verifiedFilesCount = 135;
  }

  if (input && input.action === 'resolve_insight') {
    data.success = true;
    return;
  }

  // Fetch HR/Visa cases for AI flags
  var grCase = new GlideRecord(caseTable);
  grCase.addActiveQuery();
  grCase.setLimit(5);
  grCase.query();

  while (grCase.next()) {
    data.insights.push({
      sys_id: grCase.getUniqueValue(),
      insight_id: "AI-FLG-" + Math.floor(1000 + Math.random() * 9000),
      student_name: grCase.subject_person.getDisplayValue() || grCase.opened_for.getDisplayValue() || "Student",
      case_id: grCase.getValue('number') || "VG-00000",
      category: "Financial Proof",
      severity: "High",
      summary: "Bank statement balance shortfall detected ($2,400 under I-20 minimum requirement)."
    });
  }

  // Fallback sample data if no GlideRecords found
  if (data.insights.length === 0) {
    data.insights = [
      {
        sys_id: "401",
        insight_id: "AI-FLG-8021",
        student_name: "John Doe",
        case_id: "VG-00125",
        category: "Financial Proof",
        severity: "High",
        summary: "Bank statement balance shortfall detected ($2,400 under SEVIS I-20 requirement)."
      },
      {
        sys_id: "402",
        insight_id: "AI-FLG-8022",
        student_name: "Maria Garcia",
        case_id: "VG-00128",
        category: "OPT/CPT Limit",
        severity: "High",
        summary: "Accumulated full-time CPT exceeds 12 months, triggering OPT ineligibility alert."
      },
      {
        sys_id: "403",
        insight_id: "AI-FLG-8023",
        student_name: "Likitha Sri",
        case_id: "VG-00129",
        category: "OPT/CPT Limit",
        severity: "Medium",
        summary: "Employer E-Verify ID discrepancy between Form I-983 and USCIS registry."
      },
      {
        sys_id: "404",
        insight_id: "AI-FLG-8024",
        student_name: "Alex Smith",
        case_id: "VG-00126",
        category: "Financial Proof",
        severity: "Low",
        summary: "Sponsor affidavit signature date is greater than 180 days from start date."
      }
    ];
  }
})();
